const { copyFileSync, mkdirSync } = require('node:fs');
const { join } = require('node:path');

const { withDangerousMod } = require('expo/config-plugins');

/** Generated by scripts/render-brand-assets.mjs from docs/design/logo. */
const SOURCE_DIR = 'assets/notification';
const DENSITIES = ['mdpi', 'hdpi', 'xhdpi', 'xxhdpi', 'xxxhdpi'];
/** Drawable names the recording notification asks for (recordingController.ts). */
const SMALL_ICON = 'ic_stat_tolitoli';
const LARGE_ICON = 'tolitoli_notification_large';

/**
 * Copies the Tolitoli mark into Android drawables: the white silhouette for the status bar
 * and notification header, and the colour mark as the notification's large icon.
 */
module.exports = function withNotificationIcons(config) {
  return withDangerousMod(config, [
    'android',
    (mod) => {
      const { projectRoot, platformProjectRoot } = mod.modRequest;
      const res = join(platformProjectRoot, 'app/src/main/res');
      for (const density of DENSITIES) {
        const dir = join(res, `drawable-${density}`);
        mkdirSync(dir, { recursive: true });
        copyFileSync(
          join(projectRoot, SOURCE_DIR, `${SMALL_ICON}-${density}.png`),
          join(dir, `${SMALL_ICON}.png`),
        );
      }
      const nodpi = join(res, 'drawable-nodpi');
      mkdirSync(nodpi, { recursive: true });
      copyFileSync(
        join(projectRoot, SOURCE_DIR, `${LARGE_ICON}.png`),
        join(nodpi, `${LARGE_ICON}.png`),
      );
      return mod;
    },
  ]);
};
